foreach ($m in @('GET','POST')) {
  try {
    $r = Invoke-WebRequest -Uri ($base + "/api/v3.0/portal/appLogin/apps") -Method $m -ContentType 'application/json' -Headers $h -Body '{}' -TimeoutSec 12 -UseBasicParsing
    "($m+Bearer) HTTP $($r.StatusCode) CT:$($r.Headers['Content-Type']) BODY: $($r.Content.Substring(0,[Math]::Min(400,$r.Content.Length)))"
  } catch [System.Net.WebException] {
    $resp = $_.Exception.Response
